    .{ .cause = error.RelationalResidentBudget, .code = "query.relational_resident_budget", .category = .limit, .action = .correct_input, .message = "The relational query exceeds its resident-memory budget. Its output is incomplete; review the configured capacity before starting a new execution." },
    .{ .cause = error.RelationalSpillBudget, .code = "query.relational_spill_budget", .category = .limit, .action = .correct_input, .message = "Retained relational state exceeds its storage budget. The result is incomplete; quota pressure never permits truncation." },
