    .{ .cause = error.CatalogOwnerChanged, .code = "query.catalog_owner_changed", .category = .conflict, .action = .inspect_scope, .message = "The catalog resource is inactive or its owner no longer matches this query connection. Inspect the current deployment scope before opening another query." },
