    .{ .cause = error.QueryDraftNotFound, .code = "query.draft_absent", .category = .lifecycle, .action = .inspect_status, .message = "The selected draft generation is absent in this authorized observation. Inspect the exact generation and earlier accepted query identities before reviewing another generation." },
